CREATE FUNCTION PUBLIC.CREATE_VIRTUAL_CARD(P_NAME TEXT, P_SPENDING_CAP_CENTS BIGINT, P_END_DATE DATE) RETURNS JSONB LANGUAGE PLPGSQL SECURITY DEFINER SET SEARCH_PATH = PUBLIC AS $$ DECLARE V_UID UUID; V_NAME TEXT; V_ID UUID; V_SPENDING_CAP_CENTS BIGINT; V_SPENT_CENTS BIGINT; V_STATUS TEXT; V_END_DATE DATE; V_LAST4 TEXT; BEGIN V_UID := AUTH.UID(); IF V_UID IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED' USING ERRCODE = '28000'; END IF; V_NAME := TRIM(P_NAME); IF V_NAME IS NULL OR CHAR_LENGTH(V_NAME) < 1 OR CHAR_LENGTH(V_NAME) > 60 THEN RAISE EXCEPTION 'INVALID_NAME'; END IF; IF V_NAME !~ '^[A-Za-z0-9 _-]+$' THEN RAISE EXCEPTION 'INVALID_NAME'; END IF; IF P_SPENDING_CAP_CENTS IS NULL OR P_SPENDING_CAP_CENTS <= 0 OR P_SPENDING_CAP_CENTS > 1000000 THEN RAISE EXCEPTION 'INVALID_SPENDING_CAP'; END IF; IF P_END_DATE IS NULL OR P_END_DATE <= CURRENT_DATE OR P_END_DATE > CURRENT_DATE + 730 THEN RAISE EXCEPTION 'INVALID_END_DATE'; END IF; INSERT INTO VIRTUAL_CARDS (USER_ID, NAME, SPENDING_CAP_CENTS, SPENT_CENTS, STATUS, END_DATE, LAST4) VALUES (V_UID, V_NAME, P_SPENDING_CAP_CENTS, 0, 'active', P_END_DATE, LPAD((FLOOR(RANDOM() * 10000))::INT::TEXT, 4, '0')) RETURNING ID, NAME, SPENDING_CAP_CENTS, SPENT_CENTS, STATUS, END_DATE, LAST4 INTO V_ID, V_NAME, V_SPENDING_CAP_CENTS, V_SPENT_CENTS, V_STATUS, V_END_DATE, V_LAST4; RETURN JSONB_BUILD_OBJECT('id', V_ID, 'name', V_NAME, 'spending_cap_cents', V_SPENDING_CAP_CENTS, 'spent_cents', V_SPENT_CENTS, 'status', V_STATUS, 'end_date', V_END_DATE, 'last4', V_LAST4); END; $$; REVOKE ALL ON FUNCTION PUBLIC.CREATE_VIRTUAL_CARD(TEXT, BIGINT, DATE) FROM PUBLIC, ANON; GRANT EXECUTE ON FUNCTION PUBLIC.CREATE_VIRTUAL_CARD(TEXT, BIGINT, DATE) TO AUTHENTICATED;
